import { useState, useEffect } from 'react';
import { Search, RefreshCw, AlertCircle, UtensilsCrossed } from 'lucide-react';
import MenuItemCard from './MenuItemCard';
import api from "@services/common/api";


// ============================================
// SKELETON - Responsive
// ============================================
const CardSkeleton = () => (
  <div
    className="
      bg-white rounded-2xl shadow-sm border border-gray-100 animate-pulse

      /* MOBILE: vertical */
      p-4

      /* TABLET: horizontal */
      sm:flex sm:gap-4 sm:p-4

      /* DESKTOP: vertical again */
      lg:flex-col lg:p-5
    "
  >
    {/* Image Skeleton */}
    <div
      className="
        bg-gray-100 rounded-xl

        /* MOBILE */
        w-full h-36 mb-3

        /* TABLET */
        sm:w-32 sm:h-32 sm:min-w-[8rem] sm:mb-0

        /* DESKTOP */
        lg:w-full lg:h-36 lg:mb-4
      "
    />

    {/* Content Skeleton */}
    <div className="flex-1">
      <div className="w-32 h-5 bg-gray-100 rounded mb-2" />
      <div className="w-20 h-6 bg-gray-100 rounded mb-3 sm:mb-2 lg:mb-4" />

      <div className="flex justify-between mb-3 sm:mb-2 lg:mb-4">
        <div className="w-24 h-4 bg-gray-100 rounded" />
        <div className="w-16 h-5 bg-gray-100 rounded-full" />
      </div>

      <div className="flex gap-2">
        <div className="flex-1 h-9 sm:h-8 lg:h-9 bg-gray-100 rounded-xl" />
        <div className="flex-1 h-9 sm:h-8 lg:h-9 bg-gray-100 rounded-xl" />
        <div className="w-9 sm:w-8 lg:w-9 h-9 sm:h-8 lg:h-9 bg-gray-100 rounded-xl" />
      </div>
    </div>
  </div>
);

// ============================================
// MAIN COMPONENT
// ============================================
const MenuItemsGrid = ({ selectedCategory, onEditItem }) => {
  const [menuItems, setMenuItems] = useState([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // ------------------------------------
  // FALLBACK DATA
  // ------------------------------------
  const fallbackItems = [
    { id: 1, name: 'Paneer Tikka', price: 250, category: 'starters', stock: 25, available: true },
    { id: 2, name: 'Butter Naan', price: 45, category: 'main-course', stock: 100, available: true },
    { id: 3, name: 'Biryani', price: 320, category: 'main-course', stock: 15, available: true },
    { id: 4, name: 'Mango Lassi', price: 90, category: 'drinks', stock: 50, available: true },
    { id: 5, name: 'Undhiyu', price: 280, category: 'main-course', stock: 0, available: false },
    { id: 6, name: 'Gujarati Thali', price: 350, category: 'main-course', stock: 20, available: true },
  ];

  // ------------------------------------
  // FETCH DATA
  // ------------------------------------
  useEffect(() => {
    fetchMenuItems();
  }, [selectedCategory]);

  const fetchMenuItems = async () => {
    try {
      setLoading(true);
      setError(null);

      // UNCOMMENT WHEN API READY
      // Need to change this or api call
       const params = selectedCategory !== 'all' ? `?category=${selectedCategory}` : '';
       var response =null;
       if(selectedCategory === 'all'){
        response = await api.get(`/secure/api/v1/foods?page=0&size=10&sortBy=name&sortDirection=asc`);
        setMenuItems(response.data.content);
       }else{
        response = await api.get(`/secure/api/v1/foods/category/${params}?page=0&size=10`);
        setMenuItems(response.data.content);
       }

      // MOCK
      await new Promise(resolve => setTimeout(resolve, 600));

    } catch (err) {
      console.error('Failed to fetch menu:', err);
      setError('Failed to load menu items');
      // setMenuItems(fallbackItems);
    } finally {
      setLoading(false);
    }
  };

  // ------------------------------------
  // HANDLERS
  // ------------------------------------
  const handleToggle = (id) => {
    setMenuItems(prev =>
      prev.map(item => (item.foodId === id ? { ...item, available: !item.available } : item))
    );
  };

  const handleDelete = (id) => {
    setMenuItems(prev => prev.filter(item => item.foodId !== id));
  };

  // ------------------------------------
  // FILTER LOGIC
  // ------------------------------------
  const filteredItems = menuItems
    .filter(item => selectedCategory === 'all' || item.category === selectedCategory)
    .filter(item => item.name.toLowerCase().includes(searchQuery.toLowerCase()));

  // ------------------------------------
  // RENDER
  // ------------------------------------
  return (
    <div className="flex-1 min-w-0">

      {/* ================================= */}
      {/* SEARCH BAR - Responsive           */}
      {/* ================================= */}
      <div
        className="
          flex items-center gap-2 bg-white rounded-xl border border-gray-200 shadow-sm
          focus-within:border-blue-400 focus-within:ring-2 focus-within:ring-blue-100
          transition-all mb-4

          /* MOBILE */
          px-3 py-2.5

          /* TABLET+ */
          sm:px-4 sm:py-3 sm:mb-6
        "
      >
        <Search className="w-5 h-5 text-gray-400 flex-shrink-0" />
        <input
          type="text"
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          placeholder="Search menu items..."
          className="
            bg-transparent outline-none flex-1 min-w-0
            text-gray-800 placeholder-gray-400

            /* MOBILE */
            text-sm

            /* TABLET+ */
            sm:text-base
          "
        />
        {searchQuery && (
          <button
            onClick={() => setSearchQuery('')}
            className="text-gray-400 hover:text-gray-600 text-sm font-medium flex-shrink-0 ml-1"
          >
            Clear
          </button>
        )}
      </div>

      {/* ================================= */}
      {/* CONTENT STATES                    */}
      {/* ================================= */}

      {loading ? (
        // ------------------------------------
        // SKELETON GRID - Responsive
        // ------------------------------------
        <div
          className="
            grid gap-4

            /* MOBILE: 1 column */
            grid-cols-1

            /* TABLET: 1 column (horizontal cards) */
            sm:grid-cols-1

            /* MEDIUM DESKTOP: 2 columns */
            lg:grid-cols-2

            /* LARGE DESKTOP: 3 columns */
            xl:grid-cols-3
          "
        >
          {[1, 2, 3, 4, 5, 6].map(i => (
            <CardSkeleton key={i} />
          ))}
        </div>

      ) : error && menuItems.length === 0 ? (
        // ------------------------------------
        // ERROR STATE - Responsive
        // ------------------------------------
        <div
          className="
            bg-white rounded-2xl border border-gray-100 text-center

            /* MOBILE */
            p-8

            /* TABLET+ */
            sm:p-12
          "
        >
          <AlertCircle
            className="
              text-red-300 mx-auto mb-3

              /* MOBILE */
              w-12 h-12

              /* TABLET+ */
              sm:w-16 sm:h-16 sm:mb-4
            "
          />
          <p className="text-red-600 font-medium mb-2 text-sm sm:text-base">
            {error}
          </p>
          <button
            onClick={fetchMenuItems}
            className="
              flex items-center gap-2 mx-auto px-4 py-2 text-sm
              text-blue-700 bg-blue-50 hover:bg-blue-100
              rounded-xl transition-colors font-medium
            "
          >
            <RefreshCw className="w-4 h-4" />
            Try Again
          </button>
        </div>

      ) : filteredItems.length === 0 ? (
        // ------------------------------------
        // EMPTY STATE - Responsive
        // ------------------------------------
        <div
          className="
            bg-white rounded-2xl border border-gray-100 text-center

            /* MOBILE */
            p-8

            /* TABLET+ */
            sm:p-12
          "
        >
          <UtensilsCrossed
            className="
              text-blue-200 mx-auto mb-3

              /* MOBILE */
              w-12 h-12

              /* TABLET+ */
              sm:w-16 sm:h-16 sm:mb-4
            "
          />
          <p className="text-gray-700 font-medium mb-1 text-sm sm:text-base">
            No items found
          </p>
          <p className="text-gray-500 text-xs sm:text-sm">
            {searchQuery
              ? `No results for "${searchQuery}"`
              : 'Add your first menu item to get started'}
          </p>
        </div>

      ) : (
        // ------------------------------------
        // ITEMS GRID - Responsive
        // ------------------------------------
        <div
          className="
            grid gap-4

            /* MOBILE: 1 column vertical cards */
            grid-cols-1

            /* TABLET: 1 column horizontal cards */
            sm:grid-cols-1

            /* MEDIUM DESKTOP: 2 columns */
            lg:grid-cols-2

            /* LARGE DESKTOP: 3 columns */
            xl:grid-cols-3
          "
        >
          {filteredItems.map(item => (
            <MenuItemCard
              key={item.foodId}
              item={item}
              onEdit={onEditItem}
              onToggle={handleToggle}
              onDelete={handleDelete}
            />
          ))}
        </div>
      )}

      {/* ================================= */}
      {/* RESULTS COUNT - Responsive        */}
      {/* ================================= */}
      {!loading && filteredItems.length > 0 && (
        <div className="mt-4 text-center">
          <p className="text-xs sm:text-sm text-gray-500">
            Showing {filteredItems.length} of {menuItems.length} items
          </p>
        </div>
      )}
    </div>
  );
};

export default MenuItemsGrid;